# Search for test results including PASSED/FAILED
for term in ["PASSED", "FAILED", "test session"]:
    matches = await CONTEXT.search(term)
    if matches['items']:
        print(f"\n=== {term}: {len(matches['items'])} matches ===")
        for m in matches['items'][:5]:
            o = m['offset']
            t = await CONTEXT.read(max(0, o-50), 200)
            print(f"  {t[:200]}")
